result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/fixed.ts", "content": "/**
 * Q16.16 fixed-point arithmetic on 32-bit integers.
 *
 * A value is stored as a JS `number` that is always a signed 32-bit integer
 * (int32), representing real_value * 2^16. All operations are integer-exact
 * and fully deterministic: no floating-point arithmetic ever touches the
 * value path. Multiplication and division use 64-bit intermediates held in
 * BigInt, then round-to-nearest before truncating back to int32.
 *
 * Range: [-32768.0, 32767.99998...], resolution (LSB) = 1/65536.
 */

export type i32 = number;

export const ONE_RAW = 0x10000; // 65536 = 1.0
const K = BigInt(ONE_RAW);
const HALF_LSB = 0x8000n; // 2^15, rounding threshold for Q16.16

/** Wrap an arbitrary integer to signed 32-bit. */
export function wrap32(n: number): i32 {
  return n | 0;
}

/** Convert a float to fixed-point at the boundary (truncates toward zero). */
export function fromFloat(f: number): i32 {
  return (f * ONE_RAW) | 0;
}

/** Convert fixed-point to float at the boundary (exact for representable values). */
export function toFloat(v: i32): number {
  return v / ONE_RAW;
}

/** Saturating-free wrapping add on int32. */
export function add(a: i32, b: i32): i32 {
  return (a + b) | 0;
}

/** Wrapping subtract on int32. */
export function sub(a: i32, b: i32): i32 {
  return (a - b) | 0;
}

/** Negate (wraps on INT32_MIN). */
export function neg(a: i32): i32 {
  return (-a) | 0;
}

/**
 * Fixed-point multiply: round(a.real * b.real), with the 64-bit product
 * a.raw * b.raw computed exactly via BigInt, then rounded to nearest LSB
 * (half away from zero) and wrapped to int32.
 */
export function mul(a: i32, b: i32): i32 {
  const p = BigInt(a | 0) * BigInt(b | 0); // exact 64-bit intermediate
  const negative = p < 0n;
  const mag = negative ? -p : p;
  let q = mag >> 16n; // scale back by 2^16
  if ((mag & HALF_LSB) !== 0n) q += 1n; // round half away from zero
  return Number(negative ? -q : q) | 0;
}

/**
 * Fixed-point divide: round(a.real / b.real). Computes
 * (a.raw << 16) / b.raw exactly via BigInt, rounds half away from zero,
 * wraps to int32. Throws on zero divisor.
 */
export function div(a: i32, b: i32): i32 {
  const d = BigInt(b | 0);
  if (d === 0n) throw new Error('fixed.div: division by zero');
  const n = BigInt(a | 0) << 16n; // exact 64-bit intermediate
  const negative = n < 0n !== d < 0n;
  const nmag = n < 0n ? -n : n;
  const dmag = d < 0n ? -d : d;
  let q = nmag / dmag;
  const r = nmag % dmag;
  if (r * 2n >= dmag) q += 1n; // round half away from zero
  return Number(negative ? -q : q) | 0;
}
