result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/sim.ts", "content": "/**
 * Deterministic 3-body gravity toy, stepped entirely in Q16.16 fixed-point.
 *
 * Semi-implicit (symplectic) Euler integration with Plummer softening so the
 * force stays bounded. Every quantity is an int32 raw fixed-point value;
 * there are no floating-point operations anywhere on the simulation path.
 * Trajectories are hashed with FNV-1a over the raw int32 state words.
 */

import { add, div, mul, sub, ONE_RAW, type i32 } from './fixed.js';

export const BODIES = 3;
export const STATE_WORDS = BODIES * 4; // x, y, vx, vy per body

// Physical constants, hardcoded as raw Q16.16 integers (no float conversion).
export const G_RAW: i32 = 32768; // G     = 0.5
export const MASS_RAW: i32 = 65536; // m     = 1.0
export const DT_RAW: i32 = 512; // dt    = 1/128
export const SOFTEN_RAW: i32 = 1024; // eps^2 = 1/64

/**
 * Initial conditions: equal masses on a Lagrange triangle (circumradius 1),
 * tangential velocities for near-circular rotation. All raw int32.
 */
export const INITIAL_STATE: Int32Array = Int32Array.of(
  //  body        x          y       vx         vy
  /* A */ 65536, 0, 0, 35213,
  /* B */ -32768, 56756, -30496, -17607,
  /* C */ -32768, -56756, 30496, -17607
);

/**
 * Integer floor square root of a nonnegative integer (< 2^53), digit by
 * digit in base 4 using exact integer arithmetic. Returns floor(sqrt(n)).
 */
export function isqrt(n: number): number {
  let rest = n;
  let res = 0;
  let bit = 1;
  while (bit <= rest) bit *= 4;
  bit /= 4;
  while (bit >= 1) {
    const t = res + bit;
    if (rest >= t) {
      rest -= t;
      res = res / 2 + bit;
    } else {
      res = res / 2;
    }
    bit /= 4;
  }
  return res | 0;
}

/**
 * Fixed-point square root: given v.raw = V, returns floor(sqrt(V << 16)),
 * i.e. round-down of sqrt(real(V)) in Q16.16.
 */
export function sqrtFixed(v: i32): i32 {
  return isqrt(v * ONE_RAW) | 0;
}

/** One semi-implicit Euler step; mutates `s` in place. */
export function step(s: Int32Array): void {
  const ax = new Int32Array(BODIES);
  const ay = new Int32Array(BODIES);

  for (let i = 0; i < BODIES; i++) {
    let axi: i32 = 0;
    let ayi: i32 = 0;
    const xi = s[i * 4 + 0];
    const yi = s[i * 4 + 1];
    for (let j = 0; j < BODIES; j++) {
      if (j === i) continue;
      const dx = sub(s[j * 4 + 0], xi);
      const dy = sub(s[j * 4 + 1], yi);
      // softened r^2 = dx^2 + dy^2 + eps^2 (never zero)
      let r2 = add(add(mul(dx, dx), mul(dy, dy)), SOFTEN_RAW);
      if (r2 < 0) r2 = 0; // overflow guard, keeps sqrt defined
      const r = sqrtFixed(r2);
      const invR3 = div(ONE_RAW, mul(mul(r, r), r));
      const g = mul(mul(G_RAW, MASS_RAW), invR3);
      axi = add(axi, mul(dx, g));
      ayi = add(ayi, mul(dy, g));
    }
    ax[i] = axi;
    ay[i] = ayi;
  }

  // v += a*dt ; then x += v*dt (symplectic ordering)
  for (let i = 0; i < BODIES; i++) {
    s[i * 4 + 2] = add(s[i * 4 + 2], mul(ax[i], DT_RAW));
    s[i * 4 + 3] = add(s[i * 4 + 3], mul(ay[i], DT_RAW));
  }
  for (let i = 0; i < BODIES; i++) {
    s[i * 4 + 0] = add(s[i * 4 + 0], mul(s[i * 4 + 2], DT_RAW));
    s[i * 4 + 1] = add(s[i * 4 + 1], mul(s[i * 4 + 3], DT_RAW));
  }
}

/** FNV-1a (32-bit) over the raw int32 words of a state, big-endian bytes. */
export function fnv1aState(hash: number, s: Int32Array): number {
  let h = hash >>> 0;
  for (let i = 0; i < s.length; i++) {
    const u = s[i] >>> 0;
    h ^= u >>> 24;
    h = Math.imul(h, 16777619) >>> 0;
    h ^= (u >>> 16) & 0xff;
    h = Math.imul(h, 16777619) >>> 0;
    h ^= (u >>> 8) & 0xff;
    h = Math.imul(h, 16777619) >>> 0;
    h ^= u & 0xff;
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h;
}

const FNV_OFFSET_BASIS = 0x811c9dc5;

/**
 * Run the system for `ticks` steps from INITIAL_STATE, folding every state
 * (including the initial one) into a single FNV-1a stream. Returns the hex
 * digest of the full trajectory.
 */
export function simulate(ticks: number): string {
  const s = Int32Array.from(INITIAL_STATE);
  let h = fnv1aState(FNV_OFFSET_BASIS, s);
  for (let t = 0; t < ticks; t++) {
    step(s);
    h = fnv1aState(h, s);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}
"})
