import {
  add,
  div,
  fromFloat,
  mul,
  neg,
  ONE_RAW,
  sub,
  toFloat,
  wrap32,
} from '../src/fixed.js';

describe('Q16.16 representation', () => {
  it('maps floats to raw integers at the boundary', () => {
    expect(fromFloat(1.0)).toBe(0x10000);
    expect(fromFloat(1.5)).toBe(98304);
    expect(fromFloat(2.25)).toBe(147456);
    expect(fromFloat(3.375)).toBe(221184);
    expect(fromFloat(-0.5)).toBe(-32768);
    expect(fromFloat(0)).toBe(0);
  });

  it('round-trips representable values exactly', () => {
    for (const f of [0.25, 1.5, 2.25, 3.375, -3.75, -10.125, 100.5]) {
      expect(toFloat(fromFloat(f))).toBe(f);
    }
    expect(toFloat(ONE_RAW)).toBe(1.0);
  });

  it('wraps on int32 overflow', () => {
    expect(add(0x7fffffff, 1)).toBe(wrap32(0x80000000));
    expect(sub(-2147483648, 1)).toBe(0x7fffffff | 0);
    expect(neg(-2147483648)).toBe(-2147483648);
  });
});

describe('add/sub vectors', () => {
  it('adds and subtracts exactly', () => {
    const cases: Array<[number, number, number]> = [
      [1.5, 2.25, 3.75],
      [0.125, -0.75, -0.625],
      [-1.5, -2.25, -3.75],
      [10.5, -10.5, 0],
      [0.0000152587890625 + 1 / 65536, 0, 2 / 65536], // exact multiples of LSB
    ];
    for (const [a, b, c] of cases) {
      expect(add(fromFloat(a), fromFloat(b))).toBe(fromFloat(c));
      expect(sub(fromFloat(c), fromFloat(b))).toBe(fromFloat(a));
    }
  });
});

describe('mul vectors', () => {
  it('computes 1.5 * 2.25 = 3.375 exactly', () => {
    expect(mul(fromFloat(1.5), fromFloat(2.25))).toBe(fromFloat(3.375));
    expect(mul(fromFloat(1.5), fromFloat(2.25))).toBe(221184);
  });

  it('handles signs and rounding', () => {
    expect(mul(fromFloat(2.0), fromFloat(-3.0))).toBe(fromFloat(-6.0));
    expect(mul(fromFloat(-2.0), fromFloat(-3.0))).toBe(fromFloat(6.0));
    expect(mul(fromFloat(0.5), fromFloat(0.5))).toBe(fromFloat(0.25));
    // 1/3 * 3 = 1: (21845.33) rounds to 21845, *3 = 65535 -> rounds to 1.0
    const third = div(ONE_RAW, 3);
    expect(mul(third, 3)).toBe(ONE_RAW);
    // half-LSB rounding is away from zero
    expect(mul(1, ONE_RAW)).toBe(0); // 2^-16 * 1 -> rounds to 0
    expect(mul(0x18000, 1)).toBe(2); // 1.5 LSBs * 1 -> rounds to 2 LSBs
  });
});

describe('div', () => {
  it('divides exactly when the quotient is representable', () => {
    expect(div(fromFloat(3.375), fromFloat(1.5))).toBe(fromFloat(2.25));
    expect(div(ONE_RAW, fromFloat(4.0))).toBe(fromFloat(0.25));
    expect(div(fromFloat(-6.0), fromFloat(3.0))).toBe(fromFloat(-2.0));
  });

  it('throws on zero divisor', () => {
    expect(() => div(ONE_RAW, 0)).toThrow();
  });
});

describe('division round-trips within one LSB', () => {
  it('mul then div recovers x within 1 LSB', () => {
    // Deterministic spread of raw values; divisors kept >= 1.0 in magnitude.
    const xs = [
      fromFloat(1.234),
      fromFloat(-3.75),
      fromFloat(100.03125),
      12345, // ~0.188
      -987654, // ~-15.07
      1,
      -1,
      0x7ffffff7,
    ];
    const ys = [fromFloat(1.0), fromFloat(2.25), fromFloat(-1.5), 0x7fff0000];
    for (const x of xs) {
      for (const y of ys) {
        const back = div(mul(x, y), y);
        expect(Math.abs(back - x)).toBeLessThanOrEqual(1);
        expect(back).toBe(x === 0 ? 0 : back); // sanity: defined int32
      }
    }
  });

  it('toFloat of the recovered value matches within one LSB of float error', () => {
    const x = fromFloat(7.03125);
    const y = fromFloat(-2.5);
    const err = Math.abs(toFloat(div(mul(x, y), y)) - toFloat(x));
    expect(err).toBeLessThanOrEqual(1 / 65536 + 1e-12);
  });
});
"})
